from lib import *
S = SS('v68')
steps = [
    step("gauge 会漏掉两次抓取之间的尖峰。应用的 gauge inflight 平时是 5,有 10 个持续 2 s 的尖峰到 100(应用实际在尖峰里 20.3 s),Prometheus 每 5 s 抓一次,整个实验抓到 20 个样本:其中只有 4 个样本是 100;同时 counter busy_seconds_total 在尖峰期间累计,increase 是 19.9 s,与实际的 20.3 s 很接近。gauge 只记录抓取那一刻的值,没碰上的尖峰看不到;counter 记录累计量,两次抓取之间发生的变化会在下一次抓取时体现。", t=tl(S(1)), mark=lidx(S(1), 'gauge inflight'), done=lidx(S(1), 'counter busy'), b=bars([['10 个尖峰里 gauge 抓到的样本', 4, '4 个样本是 100'], ['应用实际在尖峰里的时间 s', 20.3, '20.3'], ['counter 的 increase s', 19.9, '19.9']], 20.3, mark=[0], cur=[1], done=[2]), kv=KV([['gauge', '20 个样本里只有 4 个碰上尖峰'], ['counter', 'increase = 19.9 s,实际 20.3 s']], ['gauge'])),
    step("counter 重启归零。应用每秒 +100,运行 20 s 后重启(counter 回到 0),再运行 20 s,实际处理 4000 个请求。抓到 39 个样本,第一个样本 400,最后一个 2000,序列里出现一次 2000 → 100 的“值变小”。最后一个样本减第一个样本是 1600;按重置规则手算(最后 − 第一个 + 重置前的最后一个值)是 3600;increase(requests_total[2m]) 是 3685,rate() × 120 也是 3685。重置前的值被算进去了,所以远大于 1600;比应用实际的 4000 少,是因为第一个样本(400)之前的增量不在样本里。", t=tl(S(2)), mark=lidx(S(2), '最后一个样本 − 第一个样本', '抓到 39'), done=lidx(S(2), 'increase(requests_total', '按重置规则手算'), b=bars([['最后样本 − 第一个样本', 1600, '1600'], ['按重置规则手算', 3600, '3600'], ['increase()', 3685, '3685'], ['应用实际处理', 4000, '4000']], 4000, mark=[0], done=[1, 2], cur=[3]), kv=KV([['直接相减', '1600,漏掉重启前的 2000'], ['increase() / rate()', '3685,把“值变小”当作重置'], ['没算进去的', '第一个样本之前的 400']], ['直接相减'])),
    step("分位数能不能跨实例聚合。A 处理 90% 的流量(2% 的请求约 500 ms),B 处理 10%(没有慢请求),共 20000 个请求。所有请求合在一起的真实 p99 是 508.7 ms;A 自己的 p99 510.1,B 的 54.2。两个预先算好的 p99 取平均(avg(req_p99_ms))是 282.2;按请求量加权平均是 464.5;histogram_quantile(0.99, sum by (le) (increase(bucket)))是 732.6。预先算好的分位数不能求平均;histogram 的桶可以先相加,但估计值是桶内线性插值得到的——慢请求都落在 (500, 1000] 这个宽桶里,估计值和真实值差得比较多。", t=tl(S(3)), mark=lidx(S(3), '两个 p99 取平均', 'histogram_quantile'), done=lidx(S(3), '真实 p99', 'A 自己', 'B 自己', '加权平均'), b=bars([['真实 p99 ms', 508.7, '508.7'], ['p99 取平均 ms', 282.2, '282.2'], ['按请求量加权 ms', 464.5, '464.5'], ['histogram_quantile ms', 732.6, '732.6']], 740, done=[0], mark=[1, 2, 3]), kv=KV([['avg(p99)', '282.2 ms,偏低'], ['加权平均', '464.5 ms,仍然偏低'], ['histogram_quantile', '732.6 ms,偏高:宽桶里线性插值']], ['avg(p99)'])),
    step("类型只是约定。一个 gauge level(10 线性升到 48 再回落到 12)和一个每秒 +10 的 counter hits_total。rate(hits_total[30s]) = 9.31(边界外推让它略低于 10)。对 gauge 用 rate(level[30s]) = 14.41,这个数没有意义:gauge 下降的那一段被当成了 counter 重置。deriv(level[30s]) = −1.25(最小二乘斜率),delta(level[30s]) = −22.76(首尾差),level 当前值 12。gauge 应该用 deriv() 或 delta()。", t=tl(S(4)), mark=lidx(S(4), 'rate(level'), done=lidx(S(4), 'rate(hits_total', 'deriv', 'delta'), b=bars([['rate(hits_total)(每秒 +10)', 9.31, '9.31'], ['rate(level):gauge 用 rate', 14.41, '14.41'], ['deriv(level)', 1.25, '−1.25'], ['delta(level)', 22.76, '−22.76']], 23, done=[0, 2, 3], mark=[1]), kv=KV([['rate(counter)', '9.31/s,合理'], ['rate(gauge)', '14.41/s,没有意义'], ['deriv / delta', '−1.25 / −22.76,对 gauge 才有意义']], ['rate(gauge)'])),
]
